-- 1. Las fechas mal puestas
update public.payments p
   set paid_at = (c.fecha_nueva::text || ' 12:00:00')::timestamptz
  from _corr c
  join public.invoices i on i.doc_type = 'factura' and i.doc_number = c.folio
  join public.payment_allocations a on a.invoice_id = i.id
 where a.payment_id = p.id
   and c.fecha_nueva is not null
   and p.method <> 'nota_credito'
   and p.paid_at::date <> c.fecha_nueva;

-- 2. Los cobros que nunca existieron. Se borran las imputaciones primero: el
--    trigger allocations_recalc deja la factura en su estado real.
delete from public.payment_allocations a
 using _corr c
  join public.invoices i on i.doc_type = 'factura' and i.doc_number = c.folio
 where a.invoice_id = i.id
   and c.fecha_nueva is null
   and exists (select 1 from public.payments p
                where p.id = a.payment_id
                  and p.method <> 'nota_credito'
                  and p.code <> 'PAG-2026-001526'
                  and p.notes is not null);

delete from public.payments p
 where p.direction = 'cobro'
   and p.notes is not null
   and p.code <> 'PAG-2026-001526'
   and not exists (select 1 from public.payment_allocations a where a.payment_id = p.id)
   and (p.notes like 'Carga de la planilla%'
        or p.notes = 'Cargado desde la cartola de pagos de venta');

-- Comprobado despues de correrlo: de las 1.798 facturas que estan en los dos
-- lados, 1.797 coinciden en fecha de pago; la unica diferencia es la 35573,
-- que se dejo a proposito.
